#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ok = 0, r = 0, x = 0, y = 0;
    // 保留原整数 x；负数不是回文，0 是回文。
    x = read();
    y = x;
    r = 0;
    // 每轮取 y 的个位接到反转结果，再用整数除法移除该位。
    while (y > 0)  {
        r = ((r * 10) + (y % 10));
        y = (y / 10);
    }
    ok = 0;
    if ((x >= 0) && (x == r))  {
        ok = 1;
    }
    // 返回约定的整数 1 或 0，比较时必须使用未被修改的 x。
    emit(ok);
    return 0;
}

